namespace Ordering;

/// <summary>Applies tier, override and channel adjustments to an order subtotal.</summary>
public sealed class PricingRules
{
    private const decimal WholesaleFactor = 0.95m;
    private const decimal LargeOrderThreshold = 500m;
    private const decimal LargeOrderDiscount = 10m;

    public decimal ApplyAdjustments(Order order, CustomerTier tier)
    {
        var subtotal = CalculateSubtotal(order);
        if (tier == CustomerTier.Blocked)
            return 0m;

        var price = ApplyTier(subtotal, tier);
        price = ApplyOverride(price, order.DiscountOverride);
        price = ApplyLargeOrderDiscount(price, subtotal);
        price = ApplyChannelAdjustment(price, order.Channel);
        return decimal.Max(0m, price);
    }

    private static decimal CalculateSubtotal(Order order) =>
        order.Lines.Sum(line => line.UnitPrice * line.Quantity);

    private static decimal ApplyTier(decimal price, CustomerTier tier) =>
        tier == CustomerTier.Wholesale ? price * WholesaleFactor : price;

    private static decimal ApplyOverride(decimal price, decimal? discountOverride)
    {
        if (discountOverride is { } ovr && ovr > 0m)
            return price - ovr;
        return price;
    }

    private static decimal ApplyLargeOrderDiscount(decimal price, decimal subtotal)
    {
        if (subtotal > LargeOrderThreshold)
            return price - LargeOrderDiscount;
        return price;
    }

    private static decimal ApplyChannelAdjustment(decimal price, OrderChannel channel) =>
        channel switch
        {
            OrderChannel.Web => price,
            OrderChannel.Phone => price + 2m,
            OrderChannel.Marketplace => price * 1.02m,
            _ => price,
        };
}
